def host_classification(protocol, code, reason=None):
    """Pure specification for metadata controls; no device truth is manufactured."""
    if protocol not in PROTOCOL_IDS or type(code) is not int:
        raise ValueError("unknown original namespace or noninteger code")
    if code in LOCAL_PROTOCOLS[protocol]["success"]:
        return 0
    kind = LOCAL_CLASSES[protocol].get(code, 4)
    if kind == REASON_REQUIRED:
        # A raw host reason must not serve as a production source witness.
        # The helper only specifies replay of already sealed device metadata.
        return reason if type(reason) is int and 1 <= reason <= 9 else 8
    return kind


def validate_world_coverage(metadata,nworld):
    """Require the actual original scalar-wp.tid entry to visit all worlds once."""
    if type(nworld) is not int or nworld<1:raise ValueError("positive integer world domain required")
    if metadata.get("bounds_size")!=nworld or tuple(metadata.get("bounds_shape",()))!=(nworld,) or metadata.get("bounds_coord_mult")!=1:raise ValueError("original producer does not cover the exact one-dimensional world domain")
    block=metadata.get("block_dim");maximum=metadata.get("max_blocks")
    if type(block) is not int or block<=0 or type(maximum) is not int or maximum<0:raise ValueError("original producer launch configuration invalid")
    if maximum and not metadata.get("grid_stride") and maximum*block<nworld:raise ValueError("original producer capped grid leaves worlds unexecuted")



def validate_static_coverage(metadata,shape):
    """Bind every original operation entry's actual static coordinate domain."""
    import math
    if not isinstance(shape,tuple) or not shape or any(type(x) is not int or x<=0 for x in shape):raise ValueError('positive original static coordinate shape required')
    total=math.prod(shape)
    if type(metadata.get('bounds_size')) is not int or metadata['bounds_size']!=total or tuple(metadata.get('bounds_shape',()))!=shape or metadata.get('bounds_coord_mult')!=1:raise ValueError('original operation child launch does not cover its exact source coordinate domain')
    block=metadata.get('block_dim');maximum=metadata.get('max_blocks')
    if type(block) is not int or block<=0 or type(maximum) is not int or maximum<0 or type(metadata.get('grid_stride')) is not bool:raise ValueError('original operation child launch configuration invalid')
    if maximum and not metadata['grid_stride'] and maximum*block<total:raise ValueError('original operation capped child grid leaves coordinates unexecuted')


def validate_native_symbol_binding(metadata,actual_handle,module_symbol,function_path):
    """Bind the function actually called, not an unused authentic bridge field."""
    if not isinstance(function_path,str) or function_path.split(".")[-1]!="_function":raise ValueError("actual native source function path differs")
    if type(actual_handle) is not int or type(module_symbol) is not int or actual_handle<=0 or module_symbol<=0:raise ValueError("actual native module/function is missing")
    if type(metadata.get("function")) is not int or metadata.get("function")!=module_symbol or actual_handle!=module_symbol:raise ValueError("actual called native function differs from original module symbol")
